suppressPackageStartupMessages({library(ggpubr); library(Seurat)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE))))
so <- readRDS("../_data/zeisel_seurat.rds"); df <- data.frame(celltype = so$celltype, Gad1 = FetchData(so,"Gad1")[,1], Snap25 = FetchData(so,"Snap25")[,1], Mbp = FetchData(so,"Mbp")[,1], nGene = so$nFeature_RNA, tissue = so$tissue)
sub <- droplevels(df[df$celltype %in% c("interneurons","pyramidal SS","pyramidal CA1"),])
p <- ggboxplot(sub, "celltype", "Gad1", color = "celltype", add = "jitter", add.params = list(size = .3, alpha = .3), palette = "jco") + stat_compare_means(comparisons = list(c("interneurons","pyramidal SS"), c("interneurons","pyramidal CA1"), c("pyramidal SS","pyramidal CA1")), label = "p.signif") + stat_compare_means(label.y = 7.5)
ggsave("v1_boxplot_pvalues.png", p, width = 5.5, height = 5, dpi = 150, bg = "white")
p <- ggviolin(df, "celltype", "nGene", fill = "celltype", add = "boxplot", add.params = list(fill = "white")) + rotate_x_text(40) + rremove("legend")
ggsave("v2_violin.png", p, width = 6.5, height = 5, dpi = 150, bg = "white")
p <- ggscatter(df, "Snap25", "nGene", color = "celltype", size = .6, add = "reg.line", conf.int = TRUE, add.params = list(color = "black")) + stat_cor(method = "spearman")
ggsave("v3_scatter_cor.png", p, width = 6.5, height = 5.5, dpi = 150, bg = "white")
s <- aggregate(Mbp ~ celltype + tissue, df, mean)
p <- ggbarplot(df, "celltype", "Mbp", fill = "tissue", add = "mean_se", position = position_dodge(.8), palette = "npg") + rotate_x_text(40)
ggsave("v4_barplot_mean_se.png", p, width = 6.5, height = 5, dpi = 150, bg = "white")
